import java.util.*;
public class Main {
    static long percentile(long[] sorted,int percent){int rank=(percent*sorted.length+99)/100;return sorted[rank-1];}
    public static void main(String[] args){Scanner s=new Scanner(System.in);long threshold=s.nextLong();int n=s.nextInt();long[] latencies=new long[n];long maxLatency=0,spikeMax=0;List<String> gcLines=new ArrayList<>();for(int i=0;i<n;i++){int second=s.nextInt();long latency=s.nextLong(),gc=s.nextLong();latencies[i]=latency;maxLatency=Math.max(maxLatency,latency);if(gc>=threshold){gcLines.add("GC "+second+" "+gc);spikeMax=Math.max(spikeMax,latency);}}long[] sorted=Arrays.copyOf(latencies,n);Arrays.sort(sorted);System.out.println("p50="+percentile(sorted,50)+" p95="+percentile(sorted,95)+" p99="+percentile(sorted,99));if(gcLines.isEmpty())System.out.println("NO_GC_SPIKE");else for(String line:gcLines)System.out.println(line);System.out.println("spikeMaxLatency="+spikeMax);System.out.println("maxLatency="+maxLatency);System.out.println(!gcLines.isEmpty()&&spikeMax==maxLatency?"GC_CORRELATED":"NOT_CORRELATED");}
}

